@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + tableNumber : int
  + numberOfSeats : int
  + isSmoking : boolean
}

class Reservation {
  + reservationDate : date
  + reservationTime : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + totalAmount : double
}

class Order {
  + dishName : string
  + unitPrice : double
  + quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "*" -- "*" Table : assigns
Waiter "1" -- "*" Bill : serves
Bill "*" -- "*" Order : contains

@enduml

